import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const errors = [];
const sources = [
  "src/media-editorial.css",
  "src/visual-qa-refinement.css",
  "src/mobile-qa-final.css",
  "src/archive-character.css",
  "src/flagship-polish.css",
  "src/newsletter.css",
  "src/first-paint-polish.css"
];
const expected = [
  "/* Generated by scripts/build-media-polish.mjs. Edit the source layers, then rebuild. */",
  ...sources.map(relative => `\n/* ${relative} */\n${fs.readFileSync(path.join(ROOT, relative), "utf8").trim()}`),
  ""
].join("\n");
const actual = fs.readFileSync(path.join(ROOT, "src/media-polish.css"), "utf8");

if (actual !== expected) errors.push("src/media-polish.css is stale; run npm run build:media-polish.");

function collectHtml(directory) {
  const files = [];
  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    if ([".git", ".vercel", "node_modules"].includes(entry.name)) continue;
    const absolute = path.join(directory, entry.name);
    if (entry.isDirectory()) files.push(...collectHtml(absolute));
    else if (entry.isFile() && entry.name.endsWith(".html")) files.push(absolute);
  }
  return files;
}

let mediaPages = 0;
for (const absolute of collectHtml(ROOT)) {
  const html = fs.readFileSync(absolute, "utf8");
  if (!html.includes('<link rel="stylesheet" href="/src/media.css">')) continue;
  mediaPages += 1;
  if (!html.includes('/src/media-polish.css?v=20260825-smooth') || !html.includes("data-media-polish")) {
    errors.push(`${path.relative(ROOT, absolute)} does not head-load the consolidated media polish bundle.`);
  }
}

const mediaHeader = fs.readFileSync(path.join(ROOT, "src/components/MediaHeader.js"), "utf8");
for (const legacy of ["media-editorial.css", "visual-qa-refinement.css", "mobile-qa-final.css", "archive-character.css", "flagship-polish.css", "newsletter.css"]) {
  if (mediaHeader.includes(legacy)) errors.push(`MediaHeader still injects ${legacy} at runtime.`);
}

for (const relative of ["episodes/index.html", "guests/index.html", "topics/index.html"]) {
  const html = fs.readFileSync(path.join(ROOT, relative), "utf8");
  if (!html.includes("static-directory-list")) errors.push(`${relative} is missing its polished first-paint directory.`);
  if (!html.includes('class="site-header media-site-header"')) errors.push(`${relative} is missing server-delivered navigation chrome.`);
}

if (errors.length) {
  console.error(`\nMedia delivery gate failed with ${errors.length} issue${errors.length === 1 ? "" : "s"}:\n`);
  errors.forEach(error => console.error(`  - ${error}`));
  process.exit(1);
}

console.log("Media delivery gate passed.");
console.log(`  Consolidated media polish sources: ${sources.length}`);
console.log(`  Head-loaded media pages: ${mediaPages}`);
console.log("  Polished archive first paint: Episodes, Guests, Topics");
